// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(address newRoundImpl) internal {
        vm.assume(true);
        bool initReverted;
        try c.initialize() {
            initReverted = false;
        } catch {
            initReverted = true;
        }
        address beforeRound;
        try c.roundImplementation() returns (address __r) { beforeRound = __r; } catch { return; }
        address beforeAllo;
        try c.alloSettings() returns (address __r) { beforeAllo = __r; } catch { return; }
        bool reverted;
        try c.updateRoundImplementation(payable(newRoundImpl)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterRound;
        try c.roundImplementation() returns (address __r) { afterRound = __r; } catch { return; }
        address afterAllo;
        try c.alloSettings() returns (address __r) { afterAllo = __r; } catch { return; }
        assertTrue((!reverted && afterRound == newRoundImpl && afterAllo == beforeAllo) || (reverted && afterRound == beforeRound && afterAllo == beforeAllo));
    }

    function testFuzz_run(address newRoundImpl) public {
        vm.assume(newRoundImpl.code.length == 0 && uint160(newRoundImpl) > 0xffff && newRoundImpl != address(this) && newRoundImpl != address(c) && newRoundImpl != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newRoundImpl != 0x000000000000000000636F6e736F6c652e6c6f67 && newRoundImpl != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newRoundImpl != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newRoundImpl);
    }

    receive() external payable {}
}
